// === Tab: mySketch ===
let T, D, dt=0.01;
var A, θ;

function setup() {
    createCanvas(4/3*windowHeight, windowHeight);
    colorMode(HSB, 1);
    D = formula(0.95, 0.7, 0.6, 3.5, 0.25, 0.1);
    let c = createVector(0.04899627, 0.021375, 1.2881122);
    let s = max(width, height) * 0.3;
    T = p=>p.copy().sub(c).mult(s);
    A = Array(999).fill().map(_=>({p:createVector(random(-1, 1), random(-1, 1), random(-1, 1)), v:createVector()}))
    θ = radians(90);
}

function draw() {
    background(0, .03);
    translate(width/2, height/2);
    scale(1, -1);
    for (a of A) {
        let q = a.p;
        let u = a.v;
        let v = D(q.x, q.y, q.z).mult(dt);
        let p = q.copy().add(v);
        stroke(h(v.mag()), s(v.dist(u)), 1);
        L(T(R(p)), T(R(q)));
        a.p = p;
        a.v = v;
    }
    θ += radians(0.02);
}

function formula(a, b, c, d, e, f) {
    return (x, y, z) => {
        let dx = (z - b)*x - d*y;
        let dy = d*x + (z - b)*y;
        let dz = c + a*z - (z*z*z)/3 -(x*x + y*y)*(1 + e*z) + f*z*x*x*x;
        return createVector(dx, dy, dz);
    }
}

function h(v) { return (v-0.03)/(0.075-0.03); }
function s(a) { return a/0.002; }

function R(p) {
    let y = p.y;
    let z = cos(θ)*p.z - sin(θ)*p.x;
    let x = sin(θ)*p.z + cos(θ)*p.x;
    return createVector(x, y, z);
}

function L(a,b) { line(a.x, a.y, b.x, b.y); }

let lapse = 0;    // mouse timer
function mousePressed(){
// prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() +
    ".jpg");
    lapse = millis();
  }
}

